module tb;
    reg  [7:0] a;
    reg  [7:0] b;
    wire [7:0] s;
    wire       overflow;

    TopModule dut (
        .a(a),
        .b(b),
        .s(s),
        .overflow(overflow)
    );

    integer errors = 0;
    reg [8:0] expected_sum;
    reg       expected_overflow;

    // Task to check results
    task check(input [7:0] test_a, input [7:0] test_b);
        begin
            a = test_a;
            b = test_b;
            #5; // Wait for propagation

            // Calculate expected values using standard Verilog signed arithmetic
            expected_sum = $signed(test_a) + $signed(test_b);
            expected_overflow = (expected_sum[8] !== expected_sum[7]);

            if (s !== expected_sum[7:0]) begin
                $display("Mismatch: a=%d, b=%d | Expected s=%d, Got s=%d", 
                         $signed(test_a), $signed(test_b), $signed(expected_sum[7:0]), $signed(s));
                errors = errors + 1;
            end

            if (overflow !== expected_overflow) begin
                $display("Overflow mismatch: a=%d, b=%d | Expected overflow=%b, Got overflow=%b", 
                         $signed(test_a), $signed(test_b), expected_overflow, overflow);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Corner cases & boundary conditions testing
        // 1. Positive + Positive (No overflow)
        check(8'sd10, 8'sd20);

        // 2. Positive + Positive (Overflow boundary: Max positive + 1)
        check(8'sd127, 8'sd1);

        // 3. Negative + Negative (No overflow)
        check(-8'sd10, -8'sd20);

        // 4. Negative + Negative (Overflow boundary: Max negative + negative)
        check(-8'sd128, -8'sd1);

        // 5. Positive + Negative (Never overflows signed addition)
        check(8'sd50, -8'sd50);
        check(8'sd127, -8'sd128);

        // 6. Zero tests
        check(8'sd0, 8'sd0);
        check(8'sd0, 8'sd127);
        check(8'sd0, -8'sd128);

        // 7. Loop through some structured edge cases
        check(8'h7F, 8'h01); // 127 + 1 -> Overflow
        check(8'h80, 8'hFF); // -128 + -1 -> Overflow
        check(8'h7F, 8'h7F); // 127 + 127 -> Overflow
        check(8'h80, 8'h80); // -128 + -128 -> Overflow

        #10;
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
